module fsm #(
    parameter s0 = 3'b000,
    parameter s1 = 3'b001,
    parameter s2 = 3'b010,
    parameter s3 = 3'b011,
    parameter s4 = 3'b100,
    parameter s5 = 3'b101
) (
    input IN,
    output reg MATCH,
    input CLK,
    input RST
);

reg [1:0] state, next_state;

parameter IDLE = 2'b00,
          DETECT_1 = 2'b01,
          DETECT_00 = 2'b10,
          DETECT_11 = 2'b11;

always @(posedge CLK or posedge RST) begin
    if (RST) state <= IDLE; else state <= next_state;
end

always @(*) begin
    next_state = state;
    MATCH = 0;

    case (state)
        IDLE: begin
            if (IN == 1)
                next_state = DETECT_1;
        end
        DETECT_1: begin
            if (IN == 0)
                next_state = DETECT_00;
        end
        DETECT_00: begin
            if (IN == 1)
                next_state = DETECT_11;
        end
        DETECT_11: begin
            if (IN == 1)
                MATCH = 1;
        end
        default: begin
            next_state = IDLE;
        end
    endcase
end

endmodule
